module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem[3:0];

integer SP = 4;

assign EMPTY = (SP == 4);
assign FULL = (SP == 0);
assign dataOut = stack_mem[SP];

always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin

            SP <= 4;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
        end else begin

            if (!RW && !FULL) begin
                stack_mem[SP] <= dataIn;
                SP <= SP - 1;
            end

            else if (RW && !EMPTY) begin
                SP <= SP + 1;
                stack_mem[SP] <= 0;
            end
        end
    end
end
endmodule
